const body = $json.body ?? $json;
const headers = $json.headers ?? {};
const tokenHeader = headers['x-govhub-token'] || headers['X-GOVHUB-TOKEN'];
const allowed = String($env.GOVHUB_TOKENS || '').split(',').map((v) => v.trim()).filter(Boolean);
if (!tokenHeader || !allowed.includes(String(tokenHeader).trim())) {
  return [{ json: { ok: false, statusCode: 401, error_code: 'AUTH_INVALID_TOKEN', message: 'invalid token' } }];
}
if (!body.mission_key || !Array.isArray(body.repos) || body.repos.length === 0 || !body.created_by) {
  return [{ json: { ok: false, statusCode: 400, error_code: 'MISSION_INTAKE_INVALID_PAYLOAD', message: 'missing required fields' } }];
}
const repos = [...new Set(body.repos.map((r) => String(r).trim()).filter(Boolean))];
if (!repos.length) {
  return [{ json: { ok: false, statusCode: 400, error_code: 'MISSION_INTAKE_INVALID_REPOS', message: 'repos must contain at least one repo_key' } }];
}
return [{ json: { ok: true, mission_key: String(body.mission_key), title: body.title || null, created_by: String(body.created_by), repos } }];
